(function () {
  var nav = document.getElementById('nav');
  if (!nav) return;
  var onScroll = function () { nav.classList.toggle('scrolled', window.scrollY > 40); };
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
})();
(function () {
  var toggle = document.getElementById('nav-toggle');
  var menu = document.getElementById('nav-menu');
  if (!toggle || !menu) return;
  toggle.addEventListener('click', function () {
    var open = menu.classList.toggle('active');
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    toggle.setAttribute('aria-label', open ? 'Fermer le menu' : 'Ouvrir le menu');
  });
  menu.querySelectorAll('a').forEach(function (a) {
    a.addEventListener('click', function () {
      menu.classList.remove('active');
      toggle.setAttribute('aria-expanded', 'false');
      toggle.setAttribute('aria-label', 'Ouvrir le menu');
    });
  });
})();
(function () {
  var related = document.querySelector('[data-related]');
  if (!related) return;
  var path = window.location.pathname;
  var inBlog = path.indexOf('/blog/') !== -1;
  var jsonPath = inBlog ? 'articles.json' : 'blog/articles.json';
  var basePath = inBlog ? '' : 'blog/';
  var contactPath = inBlog ? '../contact.html' : 'contact.html';
  fetch(jsonPath)
    .then(function (r) { return r.json(); })
    .then(function (articles) {
      var currentSlug = path.split('/').pop();
      if (currentSlug && currentSlug.indexOf('.html') === -1) currentSlug += '.html';
      var others = articles.filter(function (a) { return a.slug !== currentSlug; });
      for (var i = others.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var tmp = others[i]; others[i] = others[j]; others[j] = tmp;
      }
      var picks = others.slice(0, 2);
      if (!picks.length) return;
      var frag = document.createDocumentFragment();
      picks.forEach(function (a) {
        var card = document.createElement('a');
        card.href = basePath + a.slug;
        card.className = 'card';
        if (a.image) {
          var img = document.createElement('img');
          img.src = inBlog ? a.image : a.image.replace(/^\.\.\//, '');
          img.alt = a.title;
          img.loading = 'lazy';
          img.width = 640; img.height = 400;
          card.appendChild(img);
        }
        var body = document.createElement('div');
        body.className = 'card__body';
        if (a.tag) {
          var tag = document.createElement('span');
          tag.className = 'card__tag';
          tag.textContent = a.tag;
          body.appendChild(tag);
        }
        var title = document.createElement('h3');
        title.className = 'card__title';
        title.textContent = a.title;
        body.appendChild(title);
        if (a.desc) {
          var ex = document.createElement('p');
          ex.className = 'card__excerpt';
          ex.textContent = a.desc;
          body.appendChild(ex);
        }
        if (a.date || a.readTime) {
          var meta = document.createElement('p');
          meta.className = 'card__meta';
          meta.textContent = [a.date, a.readTime].filter(Boolean).join(' · ');
          body.appendChild(meta);
        }
        card.appendChild(body);
        frag.appendChild(card);
      });
      var cta = document.createElement('a');
      cta.href = contactPath;
      cta.className = 'card';
      var ctaBody = document.createElement('div');
      ctaBody.className = 'card__body';
      ctaBody.style.justifyContent = 'center';
      var ctaTitle = document.createElement('h3');
      ctaTitle.className = 'card__title';
      ctaTitle.textContent = 'Une question sur votre peau ?';
      var ctaText = document.createElement('p');
      ctaText.className = 'card__excerpt';
      ctaText.textContent = 'Le premier échange est gratuit. Parlons de votre projet beauté à Manosque.';
      ctaBody.appendChild(ctaTitle);
      ctaBody.appendChild(ctaText);
      cta.appendChild(ctaBody);
      frag.appendChild(cta);
      while (related.firstChild) related.removeChild(related.firstChild);
      related.appendChild(frag);
    })
    .catch(function () {  });
})();
(function () {
  var form = document.getElementById('contactForm');
  if (!form) return;
  var token = document.cookie.replace(/(?:(?:^|.*;\s*)csrf_token\s*=\s*([^;]*).*$)|^.*$/, '$1');
  if (!token) {
    var arr = new Uint8Array(16);
    (window.crypto || window.msCrypto).getRandomValues(arr);
    token = Array.from(arr, function (b) { return b.toString(16).padStart(2, '0'); }).join('');
    document.cookie = 'csrf_token=' + token + ';path=/;SameSite=Strict;Secure';
  }
  var input = document.createElement('input');
  input.type = 'hidden';
  input.name = 'csrf_token';
  input.value = token;
  form.appendChild(input);
  var ft = document.createElement('input');
  ft.type = 'hidden';
  ft.name = 'form_time';
  ft.value = Math.floor(Date.now() / 1000);
  form.appendChild(ft);
})();
(function () {
  var form = document.getElementById('contactForm');
  var isProd = /(^|\.)lumia-salon\.fr$/.test(location.hostname);
  if (form) {
    form.addEventListener('submit', function (e) {
      if (!isProd) {
        e.preventDefault();
        var s = document.getElementById('formStatus');
        if (s) {
          s.textContent = 'Démonstration : le formulaire sera actif à la mise en ligne du site. En attendant, réservez sur Planity ou appelez le 04 92 87 63 72.';
          s.className = 'form__message form__message--success';
          s.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        return;
      }
      var btn = form.querySelector('button[type="submit"]');
      if (btn) { btn.textContent = 'Envoi en cours...'; btn.disabled = true; }
    });
  }
  var params = new URLSearchParams(window.location.search);
  var statut = params.get('statut');
  var status = document.getElementById('formStatus');
  if (statut && status) {
    if (statut === 'ok') {
      status.textContent = 'Merci, votre message a bien été envoyé. Nous vous répondrons rapidement.';
      status.className = 'form__message form__message--success';
      if (form) form.reset();
    } else if (statut === 'erreur') {
      status.textContent = 'Une erreur est survenue. Réessayez ou appelez-nous au 04 92 87 63 72.';
      status.className = 'form__message form__message--error';
    }
    var anchor = document.getElementById('formulaire');
    if (anchor) anchor.scrollIntoView({ behavior: 'smooth', block: 'center' });
    window.history.replaceState({}, '', window.location.pathname);
  }
})();